export async function loadPlaygroundSource(path: string): Promise<string> { const loader = loaders[path]; if (loader === undefined) { throw new Error(`Unknown playground example: ${  path}`); } return (await loader()).source; }
export async function loadPlaygroundPayload(path: string): Promise<PlaygroundPayloadInterface> { const loader = loaders[path]; if (loader === undefined) { throw new Error(`Unknown playground example: ${  path}`); } const payload = await loader(); return { 'aliases': aliases, 'modules': await payload.loadModules(), 'source': payload.source }; }
